import{_ as e,c as a,o as r,ae as d}from"./chunks/framework.DEXG3EuZ.js";const _=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1792605191000}'),i={name:"guide/index.md"};function o(l,t,n,s,c,u){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p>Vue H5 Template 是面向移动端 H5 应用的 Vue 3 工程模板。它提供一套可以直接运行、构建和部署的基础结构，同时保留足够清晰的扩展边界。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>方案</th></tr></thead><tbody><tr><td>核心</td><td>Vue 3.5、Vite 7、TypeScript 5.9</td></tr><tr><td>路由与状态</td><td>Vue Router 4、Pinia 3、状态持久化</td></tr><tr><td>网络与国际化</td><td>Axios、Vue I18n 11</td></tr><tr><td>UI</td><td>Vant 4、NutUI 4、Varlet 3</td></tr><tr><td>工程质量</td><td>ESLint 9、Prettier、Stylelint、Vitest、GitHub Actions</td></tr><tr><td>部署</td><td>Docker、Nginx、可选 Gzip 与 PWA</td></tr></tbody></table><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><ul><li>路由表维护在 <code>src/router/routes.ts</code>，没有启用文件路由。</li><li>图标示例使用 NutUI Icons 和 iconfont，没有启用 SVG 雪碧图插件。</li><li>三套 UI 库用于模板能力展示。业务项目应选定一套主 UI 后删除不再使用的依赖、resolver 和示例。</li><li>应用只保留 Axios 请求层，避免多套请求约定并存。</li><li>Mock 仅用于本地开发，测试和生产环境默认关闭。</li></ul><p>从<a href="./start">快速开始</a>创建本地环境，或先阅读<a href="./architecture">项目架构</a>了解各模块职责。</p>',7)])])}const p=e(i,[["render",o]]);export{_ as __pageData,p as default};
